function wrap(text: string, width: number): string[] {
    const lines: string[] = []
    let current = ""
    for (const word of text.split(" ")) {
        if ((current + " " + word).trim().length > width) { lines.push(current); current = word }
        else current = (current + " " + word).trim()
    }
    if (current) lines.push(current)
    return lines
}
